steps.body:
Narrowing turns a union into one of its members. Inside `if (typeof id === "string")`, the checker knows `id` is a string, so string methods work. In the `else`, or after an `if` that returns, only `number` is left:

```typescript
function label(id: string | number): string {
  if (typeof id === "string") {
    return id.toUpperCase();
  }
  return id.toFixed(1);
}
console.log(label("ab"), label(2)); // AB 2.0
```

Comparing with `===` narrows too, and so does an early `return`. After `if (user === null) return`, the rest of the function knows `user` isn't `null`.

A truthiness check like `if (name)` removes `null` and `undefined`, but it also skips `""` and `0`, which are often real values. When zero or an empty string counts, compare with exactly what you want to rule out, like `count !== undefined`.

examples.code:
function toPixels(size: number | string): number {
  if (typeof size === "string") {
    return Number.parseInt(size, 10);
    //                     ^? (parameter) size: string
  }
  return size;
  //     ^? (parameter) size: number
}

console.log(toPixels(16));
console.log(toPixels("24px"));
console.log(toPixels("1.5em"));

function greet(name: string | null | undefined): string {
  if (name) {
    return `Hello, ${name}!`;
  }
  return "Hello, guest!";
}

function stockLine(item: string, count: number | undefined): string {
  if (!count) {
    return `${item}: not counted`;
  }
  return `${item}: ${count}`;
}

function fixedStockLine(item: string, count: number | undefined): string {
  if (count === undefined) {
    return `${item}: not counted`;
  }
  return `${item}: ${count}`;
}

console.log(greet("Ada"));
console.log(greet(null));
console.log(greet(""));
console.log(stockLine("mugs", 0));
console.log(fixedStockLine("mugs", 0));
console.log(fixedStockLine("plates", undefined));

type User = { name: string; plan: "free" | "pro" };

function badge(user: User | null): string {
  if (user === null) {
    return "guest";
  }
  return `${user.name} (${user.plan})`;
  //        ^? (parameter) user: User
}

console.log(badge({ name: "Ada", plan: "pro" }));
console.log(badge(null));

