export function normalizeQty(q: number | string | null): number {
  if (q === null) {
    return 0;
  }
  if (typeof q === "string") {
    const parsed = Number.parseInt(q, 10);
    return Number.isNaN(parsed) ? 0 : parsed;
  }
  return Math.floor(q);
}

console.log(normalizeQty(4.7));
console.log(normalizeQty("12 boxes"));
console.log(normalizeQty("none"));
console.log(normalizeQty(null));

