type Fish = { name: string; swim: () => string };
type Bird = { name: string; fly: () => string };

function move(animal: Fish | Bird): string {
  if ("swim" in animal) {
    return `${animal.name} ${animal.swim()}`;
  }
  return `${animal.name} ${animal.fly()}`;
}

const nemo: Fish = { name: "Nemo", swim: () => "swims away" };
const tweety: Bird = { name: "Tweety", fly: () => "flies off" };
console.log(move(nemo));
console.log(move(tweety));

function formatWhen(value: Date | string): string {
  if (value instanceof Date) {
    return value.toISOString().slice(0, 10);
  }
  return value;
}

console.log(formatWhen(new Date("2026-10-01T09:00:00Z")));
console.log(formatWhen("next Tuesday"));

function toList(input: string | string[]): string[] {
  if (Array.isArray(input)) {
    return input;
  }
  return [input];
}

const one = toList("tea");
const many = toList(["tea", "coffee"]);
console.log(one.length, one.join(" + "));
console.log(many.length, many.join(" + "));

