export function normalizeTags(input: string | string[] | null): string[] {
  if (input === null) {
    return [];
  }
  const tags = Array.isArray(input) ? input : input.split(",");
  return tags.map((tag) => tag.trim().toLowerCase());
}

console.log(`[${normalizeTags("TypeScript, Node ,Tips").join("|")}]`);
console.log(`[${normalizeTags([" News", "RELEASES "]).join("|")}]`);
console.log(`[${normalizeTags(null).join("|")}]`);

steps.body:
Optional chaining, `?.`, reads a property only when the value before it isn't `null` or `undefined`, and gives `undefined` otherwise. `??` then replaces `null` or `undefined` with a default. Together they read data that may be missing, and the checker types the result:

```typescript
type Order = { id: string; coupon?: { code: string } };
const order: Order = { id: "A1" };
const code = order.coupon?.code ?? "none";
//    ^? const code: string
console.log(code); // none
```

The non-null assertion, a `!` after a value, works the other way. `value!` tells the checker to treat `value` as never `null` or `undefined`, and the checker believes you. Node strips the `!` like any other type, so nothing checks it at run time. When you are wrong, the program crashes later with a `TypeError`. Check for the missing case instead, and decide what should happen.

examples.code:
type Customer = {
  name: string;
  address?: { city: string; postcode?: string };
};

const customers: Customer[] = [
  { name: "Ana", address: { city: "Lisbon", postcode: "1100-148" } },
  { name: "Ben", address: { city: "Leeds" } },
  { name: "Caro" },
];

for (const customer of customers) {
  const city = customer.address?.city ?? "unknown city";
  const postcode = customer.address?.postcode ?? "no postcode";
  console.log(`${customer.name}: ${city}, ${postcode}`);
}

const prices = new Map<string, number>([
  ["mug", 12.5],
