type Customer = { name: string; address?: { city: string } };

const customers = new Map<string, Customer>([
  ["c1", { name: "Ana", address: { city: "Lisbon" } }],
  ["c2", { name: "Ben" }],
]);
const ids = ["c1", "c2", "c9"];

for (const id of ids) {
  const customer = customers.get(id);
  if (customer === undefined) {
    console.log(`${id}: no such customer`);
    continue;
  }
  console.log(`${id}: ${customer.address?.city ?? "unknown"}`);
}
